const updateRunSchedule = `-- name: UpdateRunSchedule :one
UPDATE run_schedules
SET target        = $1,
    repo_id       = $2,
    issue_iid     = $3,
    labels        = $4,
    prompt        = $5,
    timing        = $6,
    cron_expr     = $7,
    run_at        = $8,
    timezone      = $9,
    next_fire_at  = $10,
    auto_approve  = $11,
    wait_on_limit = $12,
    mr_rework_enabled = $13,
    max_issues    = $14,
    guidance      = $15,
    model         = $16,
    override_subagent_model = $17,
    customized    = $18,
    status        = 'active',
    updated_at    = now()
WHERE id = $19 AND user_id = $20
RETURNING id, user_id, repo_id, target, issue_iid, labels, prompt, timing, cron_expr, run_at, timezone, next_fire_at, last_fired_at, auto_approve, wait_on_limit, enabled, status, created_at, updated_at, max_issues, guidance, model, override_subagent_model, last_fire, origin, catalog_slug, customized, sibling_group_id, mr_rework_enabled
`

type UpdateRunScheduleParams struct {
	Target                string             `json:"target"`
	RepoID                uuid.UUID          `json:"repo_id"`
	IssueIid              pgtype.Int8        `json:"issue_iid"`
	Labels                []byte             `json:"labels"`
	Prompt                pgtype.Text        `json:"prompt"`
	Timing                string             `json:"timing"`
	CronExpr              pgtype.Text        `json:"cron_expr"`
	RunAt                 pgtype.Timestamptz `json:"run_at"`
	Timezone              string             `json:"timezone"`
	NextFireAt            pgtype.Timestamptz `json:"next_fire_at"`
	AutoApprove           bool               `json:"auto_approve"`
	WaitOnLimit           bool               `json:"wait_on_limit"`
	MrReworkEnabled       pgtype.Bool        `json:"mr_rework_enabled"`
	MaxIssues             pgtype.Int4        `json:"max_issues"`
	Guidance              pgtype.Text        `json:"guidance"`
	Model                 pgtype.Text        `json:"model"`
	OverrideSubagentModel bool               `json:"override_subagent_model"`
	Customized            bool               `json:"customized"`
	ID                    uuid.UUID          `json:"id"`
	UserID                uuid.UUID          `json:"user_id"`
}

// Owner-scoped edit of the mutable fields. A foreign id matches no row and returns
// none, so the handler cannot edit another user's schedule. next_fire_at is recomputed
// in Go from the new timing and passed here.
//
// A config edit also REVIVES the schedule to status='active'. Without this, a terminal
// 'fired' once-schedule or a 'error'-parked schedule (repo was disconnected) could be
// edited to a valid future config that is stored but never claimed — ClaimDueSchedules
// gates on status='active' — a silently dead reschedule. Editing the config is the
// explicit act of putting a schedule back into service, so it clears the terminal/error
// state; enabled (the pause flag) is orthogonal and untouched here.
func (q *Queries) UpdateRunSchedule(ctx context.Context, arg UpdateRunScheduleParams) (RunSchedule, error) {
	row := q.db.QueryRow(ctx, updateRunSchedule,
		arg.Target,
		arg.RepoID,
		arg.IssueIid,
		arg.Labels,
		arg.Prompt,
		arg.Timing,
		arg.CronExpr,
		arg.RunAt,
		arg.Timezone,
		arg.NextFireAt,
		arg.AutoApprove,
		arg.WaitOnLimit,
		arg.MrReworkEnabled,
		arg.MaxIssues,
		arg.Guidance,
		arg.Model,
		arg.OverrideSubagentModel,
		arg.Customized,
		arg.ID,
		arg.UserID,
	)
	var i RunSchedule
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.RepoID,
		&i.Target,
		&i.IssueIid,
		&i.Labels,
		&i.Prompt,
		&i.Timing,
		&i.CronExpr,
		&i.RunAt,
		&i.Timezone,
		&i.NextFireAt,
		&i.LastFiredAt,
		&i.AutoApprove,
		&i.WaitOnLimit,
		&i.Enabled,
		&i.Status,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.MaxIssues,
		&i.Guidance,
		&i.Model,
		&i.OverrideSubagentModel,
		&i.LastFire,
		&i.Origin,
		&i.CatalogSlug,
		&i.Customized,
		&i.SiblingGroupID,
		&i.MrReworkEnabled,
	)
	return i, err
}
